/**
 * Article-write atomicity.
 *
 * Owns the invariant that a markdown file on disk always has a matching
 * `articles` row in SQLite, and vice versa. Callers never coordinate the
 * build → temp-write → DB-insert → file-commit sequence themselves.
 *
 *   const store = createArticleStore(db, outputRoot);
 *   const article = store.persistArticle(link, content, site, section, runId);
 *   // article === null  ⇒ duplicate URL, no file written, no row inserted
 */

import { mkdirSync, writeFileSync, existsSync, renameSync, rmSync } from 'fs';
