  addArticle(article: Article, runId: string): boolean;
  removeArticleForFile(url: string, filePath: string): void;
  /** ADR-0005 repair-queue flag hook: queue a just-persisted article for the next Scan's repair drain. */
  flagForRepair(url: string, reason: string): void;
}

interface ArticleStoreFileSystem {
  renameSync?: typeof renameSync;
}

function removeTempFile(path: string): void {
  try { rmSync(path, { force: true }); } catch { /* ignore cleanup */ }
}

